mapper.select:
select r.* from room r
where r.is_deleted = 0
and r.room_type = #{roomType}
  and not exists (
      select 1 from room_order o
      where o.room_id = r.id and o.status = 0 and o.is_deleted = 0
        and o.checkin_time < #{checkout} and o.checkout_time > #{checkin}
  )
order by r.room_number
limit #{limit}

select * from room
id = #{id}
and is_deleted = 0

select * from price_calendar
where room_type = #{roomType}
  and date between #{startDate} and #{endDate}
  and is_deleted = 0

select price
from price_calendar
where room_type = #{roomType}
  and date = #{date}
  and is_deleted = 0

select r.*

    , coalesce(p.price, case r.room_type when 0 then 199 when 1 then 299 when 2 then 499 end) as price

from room r

    left join price_calendar p on p.room_type = r.room_type and p.date = #{date} and p.is_deleted = 0



        and r.room_number = #{roomNumber}


        and r.room_type = #{roomType}


        and r.status = #{status}

    and r.is_deleted = 0

order by r.id

    limit #{limit} offset #{offset}

select count(*) from room


        and room_number = #{roomNumber}


        and room_type = #{roomType}


        and status = #{status}

    and is_deleted = 0
